Writing the Bank class... Finishing up the module structure with the default bank instance and wrapper functions that delegate to it. I'm also thinking through edge cases like validating transfer amounts to avoid partial mutations, and noting that non-integer types and booleans pass validation which is fine. Time to write out the file and run tests.
", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\bank-1794053343\\bank.py","content":"\"\"\"Account helpers. Balances are integer cents.\"\"\"\n\n\nclass InsufficientFunds(ValueError):\n    \"\"\"Raised when a withdrawal or transfer exceeds the source balance.\"\"\"\n\n\nclass Bank:\n    \"\"\"A set of named accounts with integer-cent balances, private to each instance.\"\"\"\n\n    def __init__(self):\n        self._accounts = {}\n\n    def open_account(self, name, initial=0):\n        if initial < 0:\n            raise ValueError(\"initial balance must be >= 0: \" + str(initial))\n        if name in self._accounts:\n            raise ValueError(\"account exists: \" + name)\n        self._accounts[name] = initial\n\n    def deposit(self, name, amount):\n        if amount <= 0:\n            raise ValueError(\"amount must be > 0: \" + str(amount))\n        if name not in self._accounts:\n            raise KeyError(name)\n        self._accounts[name] += amount\n\n    def withdraw(self, name, amount):\n        if amount <= 0:\n            raise ValueError(\"amount must be > 0: \" + str(amount))\n        if name not in self._accounts:\n            raise KeyError(name)\n        if self._accounts[name] < amount:\n            raise InsufficientFunds(\n                \"account %r balance %d < amount %d\" % (name, self._accounts[name], amount))\n        self._accounts[name] -= amount\n\n    def balance(self, name):\n        return self._accounts[name]\n\n    def transfer(self, src, dst, amount):\n        if amount <= 0:\n            raise ValueError(\"amount must be > 0: \" + str(amount))\n        if src == dst:\n            raise ValueError(\"cannot transfer to the same account: \" + src)\n        if src not in self._accounts:\n            raise KeyError(src)\n        if dst not in self._accounts:\n            raise KeyError(dst)\n        if self._accounts[src] < amount:\n            raise InsufficientFunds(\n                \"account %r balance %d < amount %d\" % (src, self._accounts[src], amount))\n        self._accounts[src] -= amount\n        self._accounts[dst] += amount\n\n\ndefault_bank = Bank()\n\n\ndef open_account(name, initial=0):\n    return default_bank.open_account(name, initial)\n\n\ndef deposit(name, amount):\n    return default_bank.deposit(name, amount)\n\n\ndef withdraw(name, amount):\n    return default_bank.withdraw(name, amount)\n\n\ndef balance(name):\n    return default_bank.balance(name)\n\n\ndef transfer(src, dst, amount):\n    return default_bank.transfer(src, dst, amount)\n"}"]]}

